    "ss_ok" to ("Hotovo: televize Samsung se připojila, běží v ní ReCaption %s." to "Hotovo: televízor Samsung sa pripojil, beží v ňom ReCaption %s."),
    "ss_ok_newer" to ("Hotovo: televize Samsung se připojila (ReCaption %s – novější než soubor v tomto zařízení, nic není potřeba nahrávat)." to "Hotovo: televízor Samsung sa pripojil (ReCaption %s – novší ako súbor v tomto zariadení, nič netreba nahrávať)."),
    "ss_other" to ("Připojila se televize LG, ne Samsung. Pro LG je tlačítko Nahrát ReCaption do televize LG." to "Pripojil sa televízor LG, nie Samsung. Pre LG je tlačidlo Nahrať ReCaption do televízora LG."),
    "ss_port" to ("Spojení s TV teď blokuje jiná aplikace · zavřít ji a zkusit znovu" to "Spojenie s TV teraz blokuje iná aplikácia · zavrieť ju a skúsiť znova"),
    "ss_test_bar" to ("ReCaption: televize je připojená. Překlad se ukáže tady." to "ReCaption: televízor je pripojený. Preklad sa ukáže tu."),
